/**
 * DriftPermissionsPlugin.kt
 *
 * The permissions plugin's native half on Android: registers each
 * permission kind enabled in drift.yaml (PermissionsConfig, generated by
 * the build) as the runtime permissions the build declared. Drift's
 * permission mechanism does the rest.
 */
package com.drift.plugin.permissions

import android.Manifest
import android.os.Build
import com.drift.runner.DriftPlugin
import com.drift.runner.DriftPluginHost
import com.drift.runner.DriftRuntimePermission

class DriftPermissionsPlugin : DriftPlugin {
    override fun onRegister(host: DriftPluginHost) {
        for (kind in PermissionsConfig.kinds.sorted()) {
            val permission = when (kind) {
                "contacts" -> DriftRuntimePermission(Manifest.permission.READ_CONTACTS)
                "calendar" -> DriftRuntimePermission(Manifest.permission.READ_CALENDAR)
                "microphone" -> DriftRuntimePermission(Manifest.permission.RECORD_AUDIO)
                // READ_MEDIA_IMAGES replaced READ_EXTERNAL_STORAGE in API 33.
                "photos" -> DriftRuntimePermission(
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                        Manifest.permission.READ_MEDIA_IMAGES
                    } else {
                        Manifest.permission.READ_EXTERNAL_STORAGE
                    }
                )
                else -> error("drift permissions plugin: unknown kind $kind")
            }
            host.registerPermission(kind, permission)
        }
    }
}
